  return p as unknown as TricksterExchangeFact;
}
export function readTricksterSkipFact(type: string, payload: unknown): TricksterSkipFact | null {
  if (type !== "trickster_exchange_skipped") return null;
  const p = data(payload);
  if (
    !p ||
    !keys(p, ["actorId", "day", "reason"]) ||
    !id(p.actorId) ||
    !id(p.day) ||
    (p.reason !== "exhausted" && p.reason !== "dead")
  )
    return null;
  return p as unknown as TricksterSkipFact;
}
export function readExileMappingFact(type: string, payload: unknown): ExileMappingFact | null {
  if (type !== "exile_target_mapped") return null;
  const p = data(payload);
  if (
    !p ||
    !keys(p, ["requestedId", "effectiveId", "missed"]) ||
    !id(p.requestedId) ||
    !id(p.effectiveId) ||
    typeof p.missed !== "boolean"
  )
    return null;
  if (p.missed && p.requestedId === p.effectiveId) return null;
  return p as unknown as ExileMappingFact;
}

/**
 * Owns pure Wild Child source death and player transformation contracts for wire consumers.
 * Inputs are identifiers and proven inert payload data; outputs are detached
 * shapes or null with original keys, limits, defaults and scalar correlations.
 * Player facts retain their original exclusion of God commit IDs and sources;
 * parsing transformation data does not convert a player or activate wolf rights.
 * For these inputs the reader never changes rules, resources, phases or action
 * authority. Proxy reflection safety belongs to Node ingress before calling;
 * browser consumers must supply inert data rather than arbitrary JS objects.
 */
import { copyEventData } from "../inert-event-data";
export const WILD_CHILD_EVENT_TYPES = [
  "wild_child_model_chosen",
  "wild_child_model_eliminated",
  "wild_child_transformed",
  "wild_child_pack_activated",
] as const;
const positive = (v: unknown): v is number => Number.isSafeInteger(v) && (v as number) > 0;
const keys = (p: Record<string, unknown>, fields: string[]) =>
  Object.keys(p).length === fields.length && fields.every((k) => Object.hasOwn(p, k));
export function readWildChildEventFact(
  type: string,
  payload: unknown,
): Record<string, unknown> | null {
  if (!(WILD_CHILD_EVENT_TYPES as readonly string[]).includes(type)) return null;
  try {
    const p = copyEventData(payload) as Record<string, unknown>;
    if (!p || Array.isArray(p) || !positive(p.actorId) || !positive(p.day)) return null;
    if (type === "wild_child_model_chosen")
      return keys(p, ["actorId", "day", "targetId"]) &&
        p.day === 1 &&
        positive(p.targetId) &&
        p.actorId !== p.targetId
        ? p
        : null;
    if (type === "wild_child_model_eliminated")
      return keys(p, [
        "actorId",
        "targetId",
        "day",
        "phase",
        "deathCommit",
        "sources",
        "deadIds",
      ]) &&
        positive(p.targetId) &&
        p.actorId !== p.targetId &&
        ["night", "day", "voting"].includes(p.phase as string) &&
        typeof p.deathCommit === "string" &&
        p.deathCommit === `wild-model:${p.actorId}:${p.targetId}:${p.day}` &&
        Array.isArray(p.deadIds) &&
        p.deadIds.length > 0 &&
        p.deadIds.every(positive) &&
        p.deadIds.includes(p.targetId) &&
        new Set(p.deadIds).size === p.deadIds.length &&
        Array.isArray(p.sources) &&
        p.sources.length > 0 &&
        p.sources.every((s) =>
          ["wolf_kill", "poison", "shot", "exile", "self_destruct"].includes(s as string),
        ) &&
        new Set(p.sources).size === p.sources.length
        ? p
        : null;
    if (type === "wild_child_transformed")
      return keys(p, ["actorId", "day", "eligibleNight", "camp", "deathCommit"]) &&
        p.camp === "wolf" &&
        p.eligibleNight === (p.day as number) + 1 &&
        typeof p.deathCommit === "string" &&
        /^wild-model:[1-9]\d*:[1-9]\d*:[1-9]\d*$/.test(p.deathCommit) &&
        Number(p.deathCommit.split(":")[1]) === p.actorId &&
        Number(p.deathCommit.split(":")[3]) === p.day &&
        Number(p.deathCommit.split(":")[2]) !== p.actorId
        ? p
        : null;
    return keys(p, ["actorId", "day", "eligibleNight"]) &&
      positive(p.eligibleNight) &&
      (p.day as number) >= (p.eligibleNight as number)
      ? p
      : null;
  } catch {
    return null;
  }
}

/** Exact actor DTO; deliberately excludes God commit IDs, batch IDs and hidden causes. */
export function readWildChildPlayerFact(
  type: string,
  payload: unknown,
): Record<string, unknown> | null {
  if (type !== "wild_child_transformed")
    return type === "wild_child_model_eliminated" ? null : readWildChildEventFact(type, payload);
  try {
    const p = copyEventData(payload) as Record<string, unknown>;
    return p &&
      keys(p, ["actorId", "day", "eligibleNight", "camp"]) &&
      positive(p.actorId) &&
      positive(p.day) &&
      p.eligibleNight === (p.day as number) + 1 &&
      p.camp === "wolf"
      ? p
      : null;
  } catch {
    return null;
  }
}

/**
 * Owns inert Wolf Sorcerer exchange and skip fact data for shared consumers.
 * Inputs are a machine event type and JSON.parse/no-reviver or proven inert
 * payload; outputs are the original detached fact shapes or null. Field, ID,
 * null and copy limits retain the existing reader policy. This browser reader
 * does not promise hostile Proxy zero-trap safety: Node ingress owns that check.
 * It never authorizes an action, reads a roster or resolves the mechanism effect.
 */
import { copyEventData } from "../inert-event-data";
export interface WolfSorcererExchangeFact {
  actorId: number;
  day: number;
  pair: [number, number] | null;
}
export interface WolfSorcererSkipFact {
  actorId: number;
  day: number;
  reason: "exhausted" | "dead" | "not_started";
}
function data(payload: unknown): Record<string, unknown> | null {
  try {
    const p = copyEventData(payload);
    return p && typeof p === "object" && !Array.isArray(p) ? (p as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}
function id(v: unknown): v is number {
  return typeof v === "number" && Number.isSafeInteger(v) && v > 0 && v < Number.MAX_SAFE_INTEGER;
}
function keys(p: Record<string, unknown>, expected: string[]): boolean {
  return Object.keys(p).length === expected.length && expected.every((k) => Object.hasOwn(p, k));
}
export function readWolfSorcererExchangeFact(
  type: string,
  payload: unknown,
): WolfSorcererExchangeFact | null {
  if (type !== "wolf_sorcerer_exchange_committed") return null;
  const p = data(payload);
  if (!p || !keys(p, ["actorId", "day", "pair"]) || !id(p.actorId) || !id(p.day)) return null;
  if (
    p.pair !== null &&
    (!Array.isArray(p.pair) ||
      p.pair.length !== 2 ||
      !id(p.pair[0]) ||
      !id(p.pair[1]) ||
      p.pair[0] >= p.pair[1])
  )
    return null;
  return p as unknown as WolfSorcererExchangeFact;
}
export function readWolfSorcererSkipFact(
  type: string,
  payload: unknown,
): WolfSorcererSkipFact | null {
  if (type !== "wolf_sorcerer_exchange_skipped") return null;
  const p = data(payload);
  if (
    !p ||
    !keys(p, ["actorId", "day", "reason"]) ||
    !id(p.actorId) ||
    !id(p.day) ||
    (p.reason !== "exhausted" && p.reason !== "dead" && p.reason !== "not_started")
  )
    return null;
  return p as unknown as WolfSorcererSkipFact;
}

/**
 * Responsibility: copy inert event payload data for shared fact readers.
 * Input: JSON.parse data without revivers, or already proven inert values;
 * output: detached primitives, dense arrays and null-prototype records.
 * Limits and rejection codes preserve the original shared-reader contract:
 * depth three, caller-selected array bound (default 128), finite numbers and
 * enumerable data descriptors only. This browser-compatible reader may trigger
 * Proxy reflection; Node ingress must reject hostile proxies before calling it.
 * It grants no action authority and owns no domain state or filesystem access.
 */
export function copyEventData(value: unknown, maxArrayLength = 128, depth = 0): unknown {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (!value || typeof value !== "object" || depth > 3) throw new Error("event_fact_not_data");
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value),
    descriptors = Object.getOwnPropertyDescriptors(value);
  if (
    (array
      ? prototype !== Array.prototype
      : prototype !== Object.prototype && prototype !== null) ||
    Object.getOwnPropertySymbols(value).length
  )
    throw new Error("event_fact_not_plain");
  const result: Record<string, unknown> = Object.create(null);
  for (const [key, field] of Object.entries(descriptors)) {
    if (array && key === "length") continue;
    if (!field.enumerable || !Object.hasOwn(field, "value")) throw new Error("event_fact_accessor");
    result[key] = copyEventData(field.value, maxArrayLength, depth + 1);
  }
  if (!array) return result;
  const length = descriptors.length?.value;
  if (
    !Number.isSafeInteger(length) ||
    length < 0 ||
    length > maxArrayLength ||
    Object.keys(result).length !== length
  )
    throw new Error("event_fact_array");
  return Array.from({ length }, (_, index) => {
    if (!Object.hasOwn(result, String(index))) throw new Error("event_fact_sparse");
    return result[String(index)];
  });
}

/**
 * Owns the exact supported locale identifiers shared by protocol consumers.
 * Input is unknown data; output is a Locale guard or the declared locale list.
 * No mutable current language or display dictionary is stored in this contract.
 */
export const LOCALES = ["zh-CN", "en"] as const;
export type Locale = (typeof LOCALES)[number];
export function isLocale(value: unknown): value is Locale {
  return typeof value === "string" && (LOCALES as readonly string[]).includes(value);
}

/**
 * Owns language-neutral victory data shared by archives, engine and presentation.
 * Inputs are declared faction/checkpoint values; outputs are outcome, claim and
 * affiliation contracts. Actual identity, death-chain timing and winner selection
 * remain engine responsibilities; these records never execute victory policy.
 */
export const FACTION_IDS = ["good", "wolf", "third_party"] as const;
export type FactionId = (typeof FACTION_IDS)[number];
export const VICTORY_CHECKPOINTS = [
  "night_settled",
  "day_interrupted",
  "exile_settled",
  "max_days_reached",
] as const;
export type VictoryCheckpoint = (typeof VICTORY_CHECKPOINTS)[number];
export interface VictoryPoint {
  day: number;
  phase: "night" | "day" | "voting";
  checkpoint: VictoryCheckpoint;
}
export type VictoryAffiliation =
  | { kind: "faction"; faction: FactionId }
  | { kind: "individual"; goalId: string }
  | { kind: "relationship"; groupId: string };
export type VictoryTarget =
  | { kind: "faction"; faction: FactionId }
  | { kind: "individual"; goalId: string; playerId: number }
  | { kind: "relationship"; groupId: string };
export type VictoryClaim = VictoryTarget & { winningPlayerIds: number[] };
export type GameOutcome =
  | {
      kind: "victory";
      primary: VictoryClaim;
      additional: VictoryClaim[];
      winningPlayerIds: number[];
    }
  | { kind: "no_winner" };
export interface SealedVictoryResult {
  winner: FactionId | null;
  reason: string;
  outcome: GameOutcome;
  decidedAt: VictoryPoint;
}

/**
 * Owns engine result and phase-summary data for recording and protocol consumers.
 * Inputs are contract identities, inspection facts and victory data; outputs
 * retain original enum-typed Camp/Phase fields, nulls and optional properties.
 * These snapshots do not select winners, resolve deaths or authorize actions.
 */
import type { Camp, EntityId, Phase } from "./identity";
import type { InspectionResult } from "./inspection";
import type { GameOutcome, VictoryPoint } from "./outcomes";

export interface GameResult {
  winner: Camp | null;
  reason: string;
  outcome: GameOutcome;
  decidedAt: VictoryPoint;
}
export type WinDecision = Omit<GameResult, "decidedAt">;

export interface SeerCheckResult {
  seerId: EntityId;
  targetId: EntityId;
  isWerewolf: boolean;
  result: Extract<InspectionResult, { kind: "camp" }>;
}

export interface NightSummary {
  wolfTarget: EntityId | null;
  deaths: EntityId[];
  seerChecks: SeerCheckResult[];
  interruptedBySelfDestruct: boolean;
}

export interface DaySummary {
  speeches: Array<{ actorId: EntityId; text: string }>;
